script:
(function () {
  'use strict';
  // Net distribution from a retirement account withdrawal.
  //   withheld = gross x (federal% + state%);  payment = gross - withheld - fee
  //   penalty  = 10% x gross (IRC 72(t)), not withheld, set aside from the payment when ticked
  //   gross needed for a target T: payment mode   G = (T + fee) / (1 - fed - state)
  //                               with penalty    G = (T + fee) / (1 - fed - state - 10%)
  // Checked in Node (scratch tests): $20,000 at 20% + 5%, $50 fee -> $4,000 + $1,000 withheld,
  //   $14,950 paid; with penalty $2,000 more -> $12,950 kept. Target $10,000 at 20% + 5%, no fee
  //   -> $13,333.33 gross; with the penalty and a $50 fee -> $10,050 / 0.65 = $15,461.54, and the
  //   forward calculation of that gross returns exactly $10,000. Rates totalling 100% -> error.
  // ---- Federal rules (statutory, not indexed) -----------------------------------------
  // 20% mandatory withholding on eligible rollover distributions paid to you: IRC 3405(c).
  // 10% default withholding on IRA and other nonperiodic payments: IRC 3405(b).
  // 10% additional tax on early distributions before age 59 1/2: IRC 72(t).
  var EARLY_PENALTY = 0.10;
  // ---------------------------------------------------------------------------------------
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function forward(gross, fed, state, fee, penalty) {
    var fedAmt = gross * fed, stateAmt = gross * state;
    var net = gross - fedAmt - stateAmt - fee;
    var pen = penalty ? gross * EARLY_PENALTY : 0;
    return { gross: gross, fedAmt: fedAmt, stateAmt: stateAmt, fee: fee, net: net, pen: pen, keep: net - pen };
  }

  function grossFor(target, fed, state, fee, penalty) {
    var share = 1 - fed - state - (penalty ? EARLY_PENALTY : 0);
    return share > 1e-9 ? (target + fee) / share : NaN;
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function neg(v) { return v > 0.004 ? '−' + money.format(v) : money.format(0); }

  function update() {
    var mode = document.getElementById('ndMode').value, amount = num('ndAmount'),
        fed = num('ndFed'), state = num('ndState'), fee = num('ndFee'),
        penalty = document.getElementById('ndPenalty').checked;
    if (isNaN(fee)) fee = 0;
    set('ndAmountLabel', mode === 'net' ? 'Gross withdrawal' : 'Amount you want to end up with');
    set('ndAmountHint', mode === 'net' ? 'The amount taken out of the account before anything is withheld.'
      : (penalty ? 'What you want left after withholding, the fee and the penalty.' : 'What you want paid to you after withholding and the fee.'));
    var error = document.getElementById('ndError');
    var totalPct = fed + state + (penalty ? EARLY_PENALTY * 100 : 0); // in percent, to avoid float drift at 100%
    var bad = [amount, fed, state].some(isNaN) || amount < 0 || fed < 0 || state < 0 || fee < 0 ||
              !(totalPct < 100);
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts and withholding rates that' +
                          (penalty ? ', with the 10% penalty,' : '') + ' add up to less than 100%.';
      return;
    }
    var gross = mode === 'net' ? amount : grossFor(amount, fed / 100, state / 100, fee, penalty);
    if (mode === 'gross' && amount === 0 && fee === 0) gross = 0;
    var r = forward(gross, fed / 100, state / 100, fee, penalty);
    set('ndMainLabel', mode === 'net' ? 'You receive' : 'Withdraw this gross amount');
    set('ndMain', money.format(mode === 'net' ? Math.max(0, r.net) : r.gross));
    set('ndCosts', money.format(r.fedAmt + r.stateAmt + r.fee));
    set('ndKeep', money.format(Math.max(0, r.keep)));
    set('ndGross', money.format(r.gross));
    set('ndFedAmt', neg(r.fedAmt));
    set('ndStateAmt', neg(r.stateAmt));
    set('ndFeeAmt', neg(r.fee));
    set('ndNet', money.format(Math.max(0, r.net)));
    set('ndPenAmt', penalty ? neg(r.pen) : 'Not included');
    set('ndShare', r.gross > 0 ? (Math.max(0, r.keep) / r.gross * 100).toFixed(1) + '%' : '–');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ndForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
